const j0 = $input.first().json || {};
const j = (j0.body && typeof j0.body === 'object') ? j0.body : j0;
const now = $now.setZone('UTC');
return [{ json: { dryRun: j.dryRun === true, day: now.toISODate(), slug: 'band-conditions-' + now.toISODate() } }];

// At most one note per day: if today's slug is already in the ham radio section, stop.
const d = $input.first().json;
const res = await this.helpers.httpRequest({ url: `https://your-blog.example/api/hamradio/posts/${d.slug}`, json: true, timeout: 15000, returnFullResponse: true, ignoreHttpStatusErrors: true });
if (res.statusCode === 200) { console.log('Ham: note for', d.day, 'already posted; nothing to do'); return []; }
if (res.statusCode !== 404) throw new Error('Could not check for today\'s note: HTTP ' + res.statusCode);
return [{ json: d }];

// Public data, no key. NOAA SWPC is primary; hamqsl (N0NBH) fills gaps. Numbers come only from here.
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const helpers = this.helpers;
async function get(url, json) { let last; for (let i = 1; i <= 3; i++) { try { return await helpers.httpRequest({ url, json, encoding: json ? undefined : 'text', timeout: 15000, headers: { 'User-Agent': 'blog-bot/1.0' } }); } catch (e) { last = e; if (i < 3) await sleep(5000); } } throw last; }
const d = $input.first().json, got = { notes: [] };
try { const f = await get('https://services.swpc.noaa.gov/products/summary/10cm-flux.json', true);
  const x = Array.isArray(f) ? f[0] : f; got.sfi = Math.round(Number(x.flux ?? x.Flux)); got.sfiTime = x.time_tag || x.TimeStamp; } catch (e) { got.notes.push('NOAA flux unavailable'); }
try { const k = await get('https://services.swpc.noaa.gov/products/noaa-planetary-k-index.json', true);
  const rows = Array.isArray(k) ? k.filter(r => r && !Array.isArray(r) ? true : r[0] !== 'time_tag') : [];
  const last = rows[rows.length - 1]; got.kp = Number(Array.isArray(last) ? last[1] : last.Kp); got.kpTime = Array.isArray(last) ? last[0] : last.time_tag;
  got.kpMax24 = Math.max(...rows.slice(-8).map(r => Number(Array.isArray(r) ? r[1] : r.Kp))); } catch (e) { got.notes.push('NOAA K index unavailable'); }
try { const fc = await get('https://services.swpc.noaa.gov/products/noaa-planetary-k-index-forecast.json', true);
  const now = Date.now(); const next = fc.filter(r => r && !Array.isArray(r) && r.observed === 'predicted' && Date.parse(r.time_tag + 'Z') > now && Date.parse(r.time_tag + 'Z') < now + 24 * 3600e3);
  if (next.length) got.kpForecastMax = Math.max(...next.map(r => Number(r.kp))); } catch (e) { got.notes.push('NOAA K forecast unavailable'); }
try { const x = String(await get('https://www.hamqsl.com/solarxml.php', false));
  const tag = (t) => { const m = x.match(new RegExp('<' + t + '>\\s*([^<]*?)\\s*</' + t + '>')); return m ? m[1] : ''; };
  got.hamqsl = { sfi: Number(tag('solarflux')) || null, k: Number(tag('kindex')), updated: tag('updated') };
  if (got.sfi == null || isNaN(got.sfi)) { got.sfi = got.hamqsl.sfi; got.sfiFrom = 'hamqsl'; }
  if (got.kp == null || isNaN(got.kp)) { got.kp = got.hamqsl.k; got.kpFrom = 'hamqsl'; } } catch (e) { got.notes.push('hamqsl unavailable'); }
if (!(got.sfi > 0) || isNaN(got.kp)) throw new Error('No usable solar flux or K index from NOAA or hamqsl: ' + got.notes.join(', '));
return [{ json: { ...d, ...got } }];

// Fixed rules, no model. The aurora lines assume about 53 N geomagnetic latitude. Set PLACE and the Kp thresholds for yours.
const PLACE = 'YOUR_TOWN';
const d = $input.first().json;
const sfi = d.sfi, kp = Math.round(d.kp * 10) / 10, kpAhead = d.kpForecastMax != null ? Math.round(d.kpForecastMax * 10) / 10 : null;
const kHigh = Math.max(kp, kpAhead || 0);
const geo = kp < 3 ? 'quiet' : kp < 4 ? 'unsettled' : kp < 5 ? 'active' : 'storm-level (G' + Math.min(5, Math.floor(kp) - 4) + ')';
const fluxWord = sfi >= 150 ? 'very high' : sfi >= 120 ? 'high' : sfi >= 90 ? 'moderate' : sfi >= 70 ? 'low' : 'very low';
let day;
if (kp >= 5) day = 'Daytime HF is likely degraded by the geomagnetic storm; 20 m is the best bet, and polar paths will be poor.';
else if (sfi >= 150) day = 'Good on 10 m, 12 m and 15 m by day, with 17 m and 20 m strong.';
else if (sfi >= 120) day = 'Good on 15 m, 17 m and 20 m by day; 10 m and 12 m likely open toward the south and on long paths.';
else if (sfi >= 90) day = 'Good on 20 m and 17 m by day; 15 m usable, 10 m only occasionally.';
else if (sfi >= 70) day = '20 m is the main daytime band; 17 m and 15 m marginal, 10 m mostly closed.';
else day = 'Upper HF is mostly closed; stick to 20 m and lower by day.';
if (kp >= 4 && kp < 5) day += ' Expect some absorption and fading on higher-latitude paths.';
let night;
if (kp < 3) night = 'Good on 40 m and 80 m at night, with low noise' + (sfi >= 120 ? '; 20 m may stay open into the evening.' : '.');
else if (kp < 5) night = '40 m usable at night; 80 m noisier than usual.';
else night = 'Night-time HF is disturbed; 40 m for regional contacts, expect high noise on 80 m.';
let aurora = '';
if (kHigh >= 6) aurora = `Aurora: Kp ${kHigh} means aurora is likely visible from ${PLACE} after dark, possibly overhead. 6 m and 2 m aurora scatter are worth trying.`;
else if (kHigh >= 5) aurora = `Aurora: Kp ${kHigh} means aurora is worth a look from ${PLACE} on the northern horizon after dark, away from city lights.`;
const D = DateTime.fromISO(d.day).toFormat('LLL d, yyyy');
const title = `HF band conditions for ${D}: solar flux ${sfi}, K ${kp}`;
const lines = [
  `<p><strong>Solar flux (10.7 cm):</strong> ${sfi} (${fluxWord})${d.sfiFrom ? ' (hamqsl)' : ''}. <strong>Planetary K index:</strong> ${kp} (${geo})${d.kpFrom ? ' (hamqsl)' : ''}${kpAhead != null ? `, forecast up to ${kpAhead} in the next 24 hours` : ''}.</p>`,
  `<p><strong>By day:</strong> ${day}</p>`,
  `<p><strong>At night:</strong> ${night}</p>`,
];
if (aurora) lines.push(`<p><strong>${aurora}</strong></p>`);
lines.push('<p><em>Read from NOAA SWPC data with simple fixed rules, generated automatically at 6 AM Mountain. Real conditions vary by path and time of day.</em></p>');
const excerpt = `Flux ${sfi}, K ${kp}. ${day.split(';')[0].replace(/\.$/, '')}.${aurora ? ' Aurora worth a look tonight.' : ''}`.slice(0, 300);
const sources = [{ url: 'https://services.swpc.noaa.gov/products/summary/10cm-flux.json', title: 'NOAA SWPC 10.7 cm solar flux' },
  { url: 'https://services.swpc.noaa.gov/products/noaa-planetary-k-index.json', title: 'NOAA SWPC planetary K index' },
  { url: 'https://services.swpc.noaa.gov/products/noaa-planetary-k-index-forecast.json', title: 'NOAA SWPC K index forecast' }];
if (d.hamqsl) sources.push({ url: 'https://www.hamqsl.com/solar.html', title: 'N0NBH solar-terrestrial data (hamqsl.com)' });
const payload = { slug: d.slug, title, date: d.day, excerpt, tags: ['Band Conditions', 'Propagation', 'HF'], readingTime: 1, content: lines.join('\n'), sources,
  editorNotes: { generatedBy: 'n8n Ham Radio Band Conditions (daily)', sfi, kp, kpForecastMax: kpAhead, sfiTime: d.sfiTime, kpTime: d.kpTime, notes: d.notes } };
// Notable day (2026-11-13: the ham note goes to X only on notable days): a geomagnetic storm now or forecast
// (Kp 5 or more, the same rule as the aurora line) or very high solar flux (150 or more). Fixed rule, no model.
const notable = kHigh >= 5 || sfi >= 150;
console.log('Ham:', title, '| aurora line:', !!aurora, '| notable for X:', notable);
return [{ json: { payload, dryRun: d.dryRun, notable } }];
